#!/bin/bash
# gen_config.sh REGION MOD [LANG_ZH] [CFG] - print build/gen_config.asm for drmario.asm
REGION=$1 MOD=$2 ZH=${3:-0} CFG=$4
case $REGION in
    reva) R=1 J=0 E=0 ;;
    ju)   R=0 J=1 E=0 ;;
    eu)   R=0 J=0 E=1 ;;
    *) echo "unknown region $REGION" >&2; exit 1 ;;
esac
# The mod edits checksummed data and needs the space of the unused data.
# optimize/bugfix stay off so the timing and the demo match the original.
cat <<END
;Generated by tools/gen_config.sh - do not edit
completeCleanup     = 0
bypassChecksum      = $MOD
removeUnused        = $MOD
removeMoreUnused    = 0
optimize            = 0
bugfix              = 0
ver_revA            = $R
ver_JU              = $J
ver_EU              = $E
MOD                 = $MOD
LANG_ZH             = $ZH
END
[ -n "$CFG" ] && echo "include $CFG"
exit 0
